void vig_io_shadow_keep(u8 op, u8 arg, u8 *dst) BANKED {
    u8 i, n;
    switch (op) {
    case VIG_OP_META:
        memcpy(dst, shadow_keep_meta + (u16)arg * VIG_META_SIZE, VIG_META_SIZE);
        break;
    case VIG_OP_TILES:
        i = (u8)(arg << 5);
        n = (u8)(156u - i);
        if (n > 32) n = 32;
        set_bkg_data(VIG_SLOT(i), n, shadow_keep_tiles + ((u16)i << 4));
        break;
    case VIG_OP_ROWS:
        for (i = (u8)(arg * 6); i < (u8)(arg * 6 + 6); ++i) {
            set_bkg_tiles(0, i, 20, 1, shadow_keep_map + (u16)i * 20);
            VBK_REG = 1;
            set_bkg_tiles(0, i, 20, 1, shadow_keep_attr + (u16)i * 20);
            VBK_REG = 0;
        }
        break;
    case VIG_OP_TEXT:
        set_bkg_tiles(0, 15, 20, 2, shadow_keep_text_t + (u16)arg * 40);
        VBK_REG = 1;
        set_bkg_tiles(0, 15, 20, 2, shadow_keep_text_a + (u16)arg * 40);
        VBK_REG = 0;
        break;
    case VIG_OP_STATE: {
        const u8 *t = shadow_keep_st_t + (u16)arg * 15u;
        const u8 *a = shadow_keep_st_a + (u16)arg * 15u;
        const u8 *s = shadow_keep_spans;
        for (i = 0; i < 4u; ++i, s += 3) {
            set_bkg_tiles(s[1], s[0], s[2], 1, t);
            VBK_REG = 1;
            set_bkg_tiles(s[1], s[0], s[2], 1, a);
            VBK_REG = 0;
            t += s[2];
            a += s[2];
        }
        break;
    }
    }
    dst;
}
